#!/usr/bin/env -S uv run --script
# /// script
# requires-python = ">=3.10"
# dependencies = ["flask", "ytmusicapi>=1.7.0", "requests"]
# ///
"""YT Music Manager — local wrapper over ytmusicapi to manage a YouTube Music
library: playlist CRUD + drag-reorder, like/unlike, library browse + search,
bulk power tools, and per-track download handoff to the Video Downloader app.

Auth: browser headers. Run `ytmusicapi browser` in this dir once to create
`browser.json` (see README). The file is gitignored.
"""
import json
from pathlib import Path

import requests
from flask import Flask, jsonify, request, render_template

try:
    from ytmusicapi import YTMusic
except ImportError:  # pragma: no cover - surfaced in UI
    YTMusic = None

APP_DIR = Path(__file__).resolve().parent
AUTH_FILE = APP_DIR / "browser.json"
PORT = 5012
# The sibling Video Downloader app (yt-dlp) we hand tracks to.
DOWNLOADER = "http://127.0.0.1:5005"

app = Flask(__name__)

# Lazy singleton so the app still boots (to show the setup screen) without auth.
_yt = None
_yt_error = None


def yt():
    """Return an authenticated YTMusic client, or raise a helpful error."""
    global _yt, _yt_error
    if _yt is not None:
        return _yt
    if YTMusic is None:
        raise RuntimeError("ytmusicapi is not installed.")
    if not AUTH_FILE.exists():
        raise RuntimeError(
            "Not authenticated. Run `ytmusicapi browser` in "
            f"{APP_DIR} to create browser.json (see README)."
        )
    try:
        _yt = YTMusic(str(AUTH_FILE))
        _yt_error = None
    except Exception as e:  # noqa: BLE001
        _yt_error = str(e)
        raise
    return _yt


def err(message, code=400):
    return jsonify({"error": str(message)}), code


def api(fn):
    """Wrap a view so ytmusicapi exceptions become clean JSON errors."""
    def wrapped(*a, **k):
        try:
            return fn(*a, **k)
        except RuntimeError as e:
            return err(e, 503)
        except Exception as e:  # noqa: BLE001
            return err(e, 500)
    wrapped.__name__ = fn.__name__
    return wrapped


# ---------- track normalization ----------

def thumb(item):
    thumbs = item.get("thumbnails") or []
    return thumbs[-1]["url"] if thumbs else None


def norm_track(t):
    """Flatten a ytmusicapi track into the shape the UI expects."""
    artists = ", ".join(a["name"] for a in (t.get("artists") or []) if a.get("name"))
    album = (t.get("album") or {})
    return {
        "videoId": t.get("videoId"),
        "setVideoId": t.get("setVideoId"),  # per-playlist item id (reorder/remove)
        "title": t.get("title"),
        "artists": artists,
        "album": album.get("name") if isinstance(album, dict) else album,
        "duration": t.get("duration"),
        "likeStatus": t.get("likeStatus"),
        "isAvailable": t.get("isAvailable", True),
        "thumb": thumb(t),
    }


# ---------- pages ----------

@app.route("/")
def index():
    return render_template(
        "index.html",
        authed=AUTH_FILE.exists() and YTMusic is not None,
        app_dir=str(APP_DIR),
    )


@app.route("/api/status")
def status():
    ok = AUTH_FILE.exists() and YTMusic is not None
    downloader_up = False
    try:
        requests.get(DOWNLOADER, timeout=0.4)
        downloader_up = True
    except Exception:  # noqa: BLE001
        pass
    return jsonify({"authed": ok, "downloader": downloader_up, "appDir": str(APP_DIR)})


# ---------- playlists ----------

@app.route("/api/playlists")
@api
def playlists():
    pls = yt().get_library_playlists(limit=200)
    out = [
        {
            "playlistId": p.get("playlistId"),
            "title": p.get("title"),
            "count": p.get("count"),
            "thumb": thumb(p),
        }
        for p in pls
    ]
    return jsonify(out)


@app.route("/api/playlist/<pid>")
@api
def playlist(pid):
    if pid == "LM":
        data = yt().get_liked_songs(limit=int(request.args.get("limit", 500)))
    else:
        data = yt().get_playlist(pid, limit=int(request.args.get("limit", 1000)))
    tracks = [norm_track(t) for t in (data.get("tracks") or [])]
    return jsonify(
        {
            "playlistId": pid,
            "title": data.get("title"),
            "description": data.get("description"),
            "privacy": data.get("privacy"),
            "trackCount": data.get("trackCount") or len(tracks),
            "tracks": tracks,
        }
    )


@app.route("/api/playlist", methods=["POST"])
@api
def create_playlist():
    b = request.get_json(force=True)
    title = (b.get("title") or "").strip()
    if not title:
        return err("Title is required.")
    pid = yt().create_playlist(
        title,
        b.get("description", ""),
        privacy_status=b.get("privacy", "PRIVATE"),
        video_ids=b.get("videoIds") or None,
    )
    # create_playlist returns the id string (or an error dict)
    if isinstance(pid, dict):
        return err(pid)
    return jsonify({"playlistId": pid})


@app.route("/api/playlist/<pid>", methods=["PATCH"])
@api
def edit_playlist(pid):
    b = request.get_json(force=True)
    kwargs = {}
    if "title" in b:
        kwargs["title"] = b["title"]
    if "description" in b:
        kwargs["description"] = b["description"]
    if "privacy" in b:
        kwargs["privacyStatus"] = b["privacy"]
    res = yt().edit_playlist(pid, **kwargs)
    return jsonify({"status": res})


@app.route("/api/playlist/<pid>", methods=["DELETE"])
@api
def delete_playlist(pid):
    res = yt().delete_playlist(pid)
    return jsonify({"status": res})


@app.route("/api/playlist/<pid>/add", methods=["POST"])
@api
def add_items(pid):
    b = request.get_json(force=True)
    video_ids = b.get("videoIds") or []
    if not video_ids:
        return err("videoIds is required.")
    res = yt().add_playlist_items(
        pid, videoIds=video_ids, duplicates=b.get("duplicates", False)
    )
    return jsonify({"status": res})


@app.route("/api/playlist/<pid>/remove", methods=["POST"])
@api
def remove_items(pid):
    b = request.get_json(force=True)
    # videos: list of {videoId, setVideoId}
    videos = b.get("videos") or []
    if not videos:
        return err("videos is required.")
    res = yt().remove_playlist_items(pid, videos)
    return jsonify({"status": res})


@app.route("/api/playlist/<pid>/move", methods=["POST"])
@api
def move_item(pid):
    """Reorder one item. moved = setVideoId to move; before = setVideoId it
    should sit in front of (null = move to end)."""
    b = request.get_json(force=True)
    moved = b.get("moved")
    before = b.get("before")
    if not moved:
        return err("moved (setVideoId) is required.")
    move_arg = (moved, before) if before else (moved,)
    res = yt().edit_playlist(pid, moveItem=move_arg)
    return jsonify({"status": res})


@app.route("/api/playlist/<pid>/reorder", methods=["POST"])
@api
def reorder_all(pid):
    """Set the playlist to an explicit order (used by Sort). Rebuilds by
    removing all items then re-adding videoIds in the requested order."""
    b = request.get_json(force=True)
    order = b.get("videoIds") or []
    current = (yt().get_playlist(pid, limit=5000).get("tracks") or [])
    if not order or not current:
        return err("Nothing to reorder.")
    yt().remove_playlist_items(pid, current)
    res = yt().add_playlist_items(pid, videoIds=order, duplicates=True)
    return jsonify({"status": res, "count": len(order)})


# ---------- likes / ratings ----------

@app.route("/api/rate", methods=["POST"])
@api
def rate():
    b = request.get_json(force=True)
    vid = b.get("videoId")
    rating = b.get("rating", "LIKE")  # LIKE | INDIFFERENT | DISLIKE
    if not vid:
        return err("videoId is required.")
    res = yt().rate_song(vid, rating)
    return jsonify({"status": res})


# ---------- search ----------

@app.route("/api/search")
@api
def search():
    q = request.args.get("q", "").strip()
    if not q:
        return err("q is required.")
    filt = request.args.get("filter", "songs")  # songs|videos|albums|playlists|artists
    results = yt().search(q, filter=filt, limit=int(request.args.get("limit", 25)))
    return jsonify([norm_track(r) for r in results])


# ---------- download handoff to Video Downloader (yt-dlp, :5005) ----------

@app.route("/api/download", methods=["POST"])
@api
def download():
    b = request.get_json(force=True)
    vid = b.get("videoId")
    if not vid:
        return err("videoId is required.")
    fmt = b.get("fmt", "mp3")
    quality = b.get("quality", "0" if fmt == "mp3" else "1080")
    url = f"https://music.youtube.com/watch?v={vid}"
    try:
        r = requests.post(
            f"{DOWNLOADER}/download",
            json={"url": url, "fmt": fmt, "quality": quality},
            timeout=5,
        )
    except requests.exceptions.ConnectionError:
        return err(
            "Video Downloader app isn't running. Open it (port 5005) and retry.",
            503,
        )
    return jsonify(r.json()), r.status_code


if __name__ == "__main__":
    print(f"YT Music Manager  →  http://127.0.0.1:{PORT}")
    app.run(host="127.0.0.1", port=PORT, debug=False, threaded=True)

