def _downloader_up():
    try:
        requests.get(DOWNLOADER, timeout=0.5)
        return True
    except Exception:  # noqa: BLE001
        return False


def _ensure_downloader():
    """Launch the Video Downloader app if it isn't already listening on :5005.
    Returns True once it's reachable, False if it never came up."""
    if _downloader_up():
        return True
    if not Path(DOWNLOADER_APP).exists():
        return False
    # -g = open in background without stealing focus from this app.
    subprocess.run(["open", "-g", DOWNLOADER_APP], check=False)
    for _ in range(30):  # up to ~15s for Flask + uv cold start
        if _downloader_up():
            return True
        time.sleep(0.5)
    return False


@app.route("/api/download", methods=["POST"])
@api
def download():
    b = request.get_json(force=True)
    vid = b.get("videoId")
    if not vid:
        return err("videoId is required.")
    fmt = b.get("fmt", "mp3")
    quality = b.get("quality", "0" if fmt == "mp3" else "1080")
    url = f"https://music.youtube.com/watch?v={vid}"
    if not _ensure_downloader():
        return err(
            "Couldn't reach or start the Video Downloader app (port 5005).", 503
        )
    try:
        r = requests.post(
            f"{DOWNLOADER}/download",
            json={"url": url, "fmt": fmt, "quality": quality},
            timeout=8,
        )
    except requests.exceptions.ConnectionError:
        return err("Video Downloader app stopped responding.", 503)
    return jsonify(r.json()), r.status_code

