# ---------- playback + offline cache ----------

def cached_path(vid):
    """Return the cached audio file for a videoId, or None. Ignores .part files."""
    if not CACHE_DIR.exists():
        return None
    for p in CACHE_DIR.glob(vid + ".*"):
        if p.is_file() and not p.name.endswith(".part"):
            return p
    return None


@app.route("/api/cached")
def cached_list():
    """Set of videoIds currently saved offline (so the UI can mark them)."""
    ids = []
    if CACHE_DIR.exists():
        ids = sorted(
            {p.stem for p in CACHE_DIR.iterdir() if p.is_file() and not p.name.endswith(".part")}
        )
    return jsonify({"ids": ids})


@app.route("/api/cache", methods=["POST"])
@api
def cache_track():
    """Download one track's audio into the offline cache via yt-dlp."""
    vid = request.get_json(force=True).get("videoId")
    if not vid:
        return err("videoId is required.")
    if cached_path(vid):
        return jsonify({"status": "already", "videoId": vid})
    CACHE_DIR.mkdir(parents=True, exist_ok=True)
    out = str(CACHE_DIR / (vid + ".%(ext)s"))
    proc = subprocess.run(
        [YT_DLP, "-f", AUDIO_FMT, "--no-playlist", "-o", out,
         f"https://music.youtube.com/watch?v={vid}"],
        capture_output=True, text=True,
    )
    p = cached_path(vid)
    if proc.returncode != 0 or not p:
        return err("Cache failed: " + (proc.stderr[-300:] or "unknown error"), 500)
    return jsonify({"status": "cached", "videoId": vid, "bytes": p.stat().st_size})


@app.route("/api/uncache", methods=["POST"])
@api
def uncache_track():
    vid = request.get_json(force=True).get("videoId")
    p = cached_path(vid)
    if p:
        p.unlink()
    return jsonify({"status": "removed", "videoId": vid})


@app.route("/api/stream/<vid>")
def stream(vid):
    """Play a track. Serves the cached file (with Range support for seeking) if
    saved offline; otherwise resolves a live audio URL and redirects to it."""
    p = cached_path(vid)
    if p:
        return send_file(str(p), conditional=True)
    try:
        proc = subprocess.run(
            [YT_DLP, "-f", AUDIO_FMT, "--no-playlist", "-g",
             f"https://music.youtube.com/watch?v={vid}"],
            capture_output=True, text=True, timeout=30,
        )
    except subprocess.TimeoutExpired:
        return err("Stream resolution timed out.", 504)
    urls = [u for u in proc.stdout.strip().splitlines() if u.startswith("http")]
    if proc.returncode != 0 or not urls:
        return err("Couldn't resolve a stream: " + (proc.stderr[-200:] or "unknown"), 502)
    return redirect(urls[0])


if __name__ == "__main__":
    print(f"YT Music Manager  →  http://127.0.0.1:{PORT}")

