// ---------- player ----------
const audio = $('#audio');
let player = { queue:[], idx:0, cur:null, shuffle:false, repeat:'off', shuf:[], si:0 };

function fmtTime(s){ s=Math.floor(s||0); return Math.floor(s/60)+':'+String(s%60).padStart(2,'0'); }
function playFrom(i){ playQueue(state.tracks.slice(), i); }
function playQueue(tracks, startIdx){
  const list = tracks.filter(t=>t.videoId);
  const targetVid = tracks[startIdx] && tracks[startIdx].videoId;
  player.queue = list;
  player.idx = Math.max(0, list.findIndex(t=>t.videoId===targetVid));
  if(player.shuffle) buildShuffle();
  $('#player').classList.remove('hidden');
  loadCurrent(true);
}
function buildShuffle(){
  const idxs=[...player.queue.keys()].filter(k=>k!==player.idx);
  for(let i=idxs.length-1;i>0;i--){ const j=Math.floor(Math.random()*(i+1)); [idxs[i],idxs[j]]=[idxs[j],idxs[i]]; }
  player.shuf=[player.idx,...idxs]; player.si=0;
}
function loadCurrent(autoplay){
  const t = player.queue[player.idx]; if(!t) return;
  player.cur = t;
  audio.src = '/api/stream/'+encodeURIComponent(t.videoId);
  audio.playbackRate = parseFloat($('#pSpeed').value);
  audio.volume = $('#pVol').value/100;
  if(autoplay) audio.play().catch(e=>toast('Playback error: '+e.message,true));
  $('#pArt').src = t.thumb||''; $('#pTitle').textContent=t.title||''; $('#pArtist').textContent=t.artists||'';
  renderTracks(); renderQueue();
}
function next(auto){
  if(player.repeat==='one' && auto){ audio.currentTime=0; audio.play(); return; }
  if(player.shuffle){
    if(player.si < player.shuf.length-1){ player.si++; player.idx=player.shuf[player.si]; }
    else if(player.repeat==='all'){ buildShuffle(); player.si=0; player.idx=player.shuf[0]; }
    else { audio.pause(); return; }
  } else {
    if(player.idx < player.queue.length-1){ player.idx++; }
    else if(player.repeat==='all'){ player.idx=0; }
    else { audio.pause(); return; }
  }
  loadCurrent(true);
}
function prev(){
  if(audio.currentTime>3){ audio.currentTime=0; return; }
  if(player.shuffle){ if(player.si>0){ player.si--; player.idx=player.shuf[player.si]; } }
  else { if(player.idx>0) player.idx--; }
  loadCurrent(true);
}
$('#pPlay').onclick=()=>{ audio.paused ? audio.play().catch(()=>{}) : audio.pause(); };
$('#pNext').onclick=()=>next(false);
$('#pPrev').onclick=prev;
$('#pShuffle').onclick=()=>{ player.shuffle=!player.shuffle; $('#pShuffle').classList.toggle('on',player.shuffle); if(player.shuffle) buildShuffle(); };
$('#pRepeat').onclick=()=>{
  player.repeat = player.repeat==='off'?'all':player.repeat==='all'?'one':'off';
  $('#pRepeat').classList.toggle('on',player.repeat!=='off');
  $('#pRepeat').title='Repeat: '+player.repeat;
  $('#pRepeat').textContent = player.repeat==='one'?'🔂':'🔁';
};
$('#pSpeed').onchange=()=>{ audio.playbackRate=parseFloat($('#pSpeed').value); };
$('#pVol').oninput=()=>{ audio.volume=$('#pVol').value/100; };
$('#pBar').oninput=()=>{ if(audio.duration) audio.currentTime=$('#pBar').value/1000*audio.duration; };
audio.addEventListener('ended',()=>next(true));
audio.addEventListener('play',()=>$('#pPlay').textContent='⏸');
audio.addEventListener('pause',()=>$('#pPlay').textContent='▶');
audio.addEventListener('timeupdate',()=>{
  if(!audio.duration) return;
  $('#pBar').value=Math.round(audio.currentTime/audio.duration*1000);
  $('#pCur').textContent=fmtTime(audio.currentTime); $('#pDur').textContent=fmtTime(audio.duration);
});
$('#pQueueBtn').onclick=()=>{ $('#queue').classList.toggle('hidden'); renderQueue(); };
$('#qClose').onclick=()=>$('#queue').classList.add('hidden');
function renderQueue(){
  if($('#queue').classList.contains('hidden')) return;
  const list=$('#qlist'); list.innerHTML='';
  player.queue.forEach((t,k)=>{
    const d=document.createElement('div');
    d.className='qrow'+(k===player.idx?' cur':'');
    d.innerHTML=`<div class="qt">${esc(t.title)}<div class="qa">${esc(t.artists)}</div></div>`;
    d.onclick=()=>{ player.idx=k; if(player.shuffle) buildShuffle(); loadCurrent(true); };
    list.appendChild(d);
  });
}
// keyboard: space=play/pause, arrows=prev/next (ignore when typing)
document.addEventListener('keydown',e=>{
  if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)) return;
  if(e.code==='Space'){ e.preventDefault(); audio.paused?audio.play().catch(()=>{}):audio.pause(); }
  else if(e.code==='ArrowRight' && e.shiftKey){ next(false); }
  else if(e.code==='ArrowLeft' && e.shiftKey){ prev(); }
});

