# ---------- metadata cache (playlist listings) ----------

def _meta_file(key):
    # keys are playlist ids / "playlists" — keep filenames safe
    safe = "".join(c if c.isalnum() or c in "-_" else "_" for c in key)
    return META_DIR / (safe + ".json")


def cache_read(key, ttl=META_TTL):
    f = _meta_file(key)
    if not f.exists():
        return None
    try:
        blob = json.loads(f.read_text())
    except Exception:  # noqa: BLE001
        return None
    if ttl is not None and (time.time() - blob.get("cachedAt", 0)) > ttl:
        return None
    return blob


def cache_write(key, data):
    META_DIR.mkdir(parents=True, exist_ok=True)
    _meta_file(key).write_text(json.dumps({"cachedAt": time.time(), "data": data}))


def cache_drop(*keys):
    for k in keys:
        f = _meta_file(k)
        if f.exists():
            f.unlink()

