async function openPlaylist(pid, opts={}){
  state.view = pid; state.sel.clear(); updateBulk();
  document.querySelectorAll('.navitem').forEach(n=>n.classList.remove('active'));
  // In-memory cache → instant tab switching. force bypasses both layers.
  let data = (!opts.force && state.plCache[pid]) ? state.plCache[pid] : null;
  if(!data){
    $('#tracks').innerHTML = '<div class="empty">Loading…</div>';
    try { data = await api('/api/playlist/'+encodeURIComponent(pid)+(opts.force?'?refresh=1':'')); }
    catch(e){ $('#tracks').innerHTML = `<div class="empty">${esc(e.message)}</div>`; return; }
    state.plCache[pid] = data;
  }
  state.tracks = data.tracks.slice(); state.title = data.title;
  state.tracks.forEach((t,i)=>t._ord=i);  // original order (LM = recently-added first)
  $('#viewTitle').textContent = data.title || '(untitled)';
  const ago = data.cachedAt ? cacheAgo(data.cachedAt) : '';
  $('#viewSub').textContent = `${data.tracks.length} tracks` + (data.privacy?` · ${data.privacy}`:'') + ago;

const esc = s => (s||'').replace(/[&<>"]/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
function cacheAgo(ts){
  const s = Math.max(0, Math.floor(Date.now()/1000 - ts));
  if(s<5) return ' · live';
  if(s<60) return ` · cached ${s}s ago`;
  if(s<3600) return ` · cached ${Math.floor(s/60)}m ago`;
  if(s<86400) return ` · cached ${Math.floor(s/3600)}h ago`;
  return ` · cached ${Math.floor(s/86400)}d ago`;
}

