def dedupe_tracks(tracks):
    """Drop phantom duplicates from ytmusicapi pagination overlap. Keyed by
    setVideoId when present (a regular playlist's per-item id, so two genuine
    copies a user added stay distinct) and by videoId otherwise (Liked Music
    has no setVideoId and can't truly contain the same song twice)."""
    seen = set()
    out = []
    for t in tracks:
        key = t.get("setVideoId") or t.get("videoId")
        if key and key in seen:
            continue
        if key:
            seen.add(key)
        out.append(t)
    return out


